window.products.push({"id":690216,"name":"zouwii Personalized Acrylic Song Acrylic Apple Music Player Album Style Cover Valentine's Day Commemorative Gift Anniversary Photo Style Custom Acryli","category":"homeandappliances","retail price":17.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61Z8taAwE8L._AC_SL1500_.jpg","description":"💖【Custom Music Board】Just select the title, album and cover art of your choice or your photo and we will solve it for you. We guarantee professional quality, no glue, no stickers. Show your love or friendship to your loved ones. 💖Acrylic frames are a plastic type material that is harder to break then glass. It allows shipping with ease and don’t have to worry about the product being damaged 💖Picture is your photo printed on vinyl, but if the picture is unable to be cropped and look neat I will choose a bigger size to have the photo work. 💖Also these items are handmade with love and attention to detail so please understand these take time. 💖Choose your favourite song / album and turn it into a custom song plaque!","images":["https://m.media-amazon.com/images/I/61Z8taAwE8L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"zouwii","source_asin":"B08RBR8DRW","category_path":"Home & Kitchen"},"sku":"BM-690216","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08RBR8DRW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08RBR8DRW","price_pending":true,"merchant_ready":false});
