window.products.push({"id":690846,"name":"Waring Commercial WSC160X 16\" Electric Crepe Maker, Cast Iron Cooking Surface, Stainless Steel Base, Includes Batter Spreader and Spatula, 120V, 1800W","category":"homeandappliances","retail price":479.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61ctW9t3caL._AC_SL1500_.jpg","description":"Create an endless variety of delicious crêpes with the Waring® WSC160X 16\" Electric Crêpe Maker. A 1\" thick, cast-iron cooking plate heats up quickly and maintains its temperature all day long. An adjustable thermostat, from 280°F to 570°F, gives you tremendous flexibility to create amazing signature dishes. A durable stainless steel base with heat-resistant carrying handle makes it easy to transport.","images":["https://m.media-amazon.com/images/I/61ctW9t3caL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Waring Commercial","source_asin":"B0BL9DPHVS","category_path":"Home & Kitchen"},"sku":"BM-690846","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BL9DPHVS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BL9DPHVS","price_pending":true,"merchant_ready":false});
